plan=json.loads((R/'plan.json').read_text());batch=json.loads((R/'batch.json').read_text());records=reg.read_records(ROOT/'research/automation/registry.jsonl');before='--before-reserve' in sys.argv;assert len(batch)==54 and sha(R/'engine.py')==plan['source_engine']['sha256'];seen=set()
for row in batch:
 sp=json.loads((ROOT/row['spec']).read_text());p=sp['parameters'];fps=row['source_fingerprints'];a=row['ETH_A_ownership_fraction'];pair=row['slow_pair_days'];weights=[1,a,1-a];assert reg.fingerprint(sp)==row['fingerprint'] and row['fingerprint'] not in seen;seen.add(row['fingerprint'])
