 for j,x in enumerate([ea,eb]):assert x['initial_capital_usdt']==10000 and x['fixed_entry_notional_usdt']==3000 and x['trend_gate_mode']=='adjacent_horizon_majority' and x['trend_lookback_days']==pair[j] and x['trend_gate_lookbacks_days']==p['ETH_slow_gate_lookbacks_days'][j]==[pair[j]-1,pair[j],pair[j]+1] and x['return_hurdle']==p['reversal_return_hurdle']==row['reversal_return_hurdle'] in [.02,.025,.03] and x['lookback_days']==p['reversal_lookback_days']==row['reversal_lookback_days'] in [3,4] and x['exit_buffer_fraction']==0
